def solve_better():
    max_d = 0
    for g in range(1, 101):
        X_g = list(range(g, 101))
        # Use a DP to find all possible sums using any number of elements from X_g
        # This is the same as the change-making problem or the knapsack problem.
        possible_sums = {0}
        for x in X_g:
            # For each x, update possible_sums
            # Since we can use x multiple times, we can iterate and update.
            # However, we only need to go up to 1810.
            # This is the unbounded knapsack problem.
            for s in range(x, 1811):
                if (s - x) in possible_sums:
                    # This is not quite right for a set.
                    # Let's use a boolean array.
                    pass

        # Correct way to do unbounded knapsack:
        sums = [False] * 1811
        sums[0] = True
        for x in X_g:
            for s in range(x, 1811):
                if sums[s - x]:
                    sums[s] = True

        for s in range(1810 - g + 1, 1811):
            if sums[s]:
                # s is a sum of elements from {g, ..., 100}
                # and we know s+g is also a sum (since g is in X_g)
                # We need to make sure g is one of the elements in the sum s+g.
                # Since g is in X_g, s+g is always a sum.
                d = max(1810 - s, s + g - 1810)
                if d > max_d:
                    max_d = d
    return max_d

